// Generate the file:// worker from the SAME source used by HTTP workers.
const fs=require('node:fs');
const path=require('node:path');
const source=fs.readFileSync(path.join(__dirname,'forced_mate.js'),'utf8')+'\n'+
 fs.readFileSync(path.join(__dirname,'mate_search_worker.js'),'utf8').replace(/^importScripts\([^\n]+\);\r?\n/,'');
fs.writeFileSync(path.join(__dirname,'worker_bundle.js'),'// Generated by build_worker_bundle.js; do not edit.\nwindow.MATE_SEARCH_WORKER_SOURCE = '+JSON.stringify(source)+';\n');
